async function exists(target) {
  try {
    await fs.access(target);
    return true;
  } catch {
    return false;
  }
}

async function readText(relativePath) {
  return fs.readFile(path.join(ROOT, relativePath), "utf8");
}

async function backup(relativePath) {
  const source = path.join(ROOT, relativePath);
  if (!(await exists(source))) return;

  const target = path.join(BACKUP_ROOT, relativePath);

  if (!DRY_RUN) {
    await fs.mkdir(path.dirname(target), { recursive: true });
    await fs.copyFile(source, target);
  }
}

async function writeFile(relativePath, content) {
  const target = path.join(ROOT, relativePath);
  const current = (await exists(target))
    ? await fs.readFile(target, "utf8")
    : null;

  if (current === content) {
    log(`bez zmian: ${relativePath}`);
    return;
  }

  if (
    current &&
    !current.includes("@generated by install-humanet-values-marketing.mjs") &&
    !FORCE &&
    ![
      "app/layout.tsx",
      "app/(protected)/layout.tsx",
      "shared/ui/Analytics.tsx",
    ].includes(relativePath)
  ) {
    throw new Error(
      `Plik ${relativePath} istnieje i nie jest zarządzany przez instalator. ` +
        `Przejrzyj go i użyj --force tylko świadomie.`,
    );
  }

  await backup(relativePath);
  log(`${current ? "aktualizacja" : "utworzenie"}: ${relativePath}`);

  if (!DRY_RUN) {
    await fs.mkdir(path.dirname(target), { recursive: true });
    await fs.writeFile(target, content, "utf8");
  }
}

async function patchFile(relativePath, patcher) {
  const target = path.join(ROOT, relativePath);

  if (!(await exists(target))) {
    throw new Error(`Brak wymaganego pliku do rozszerzenia: ${relativePath}`);
  }

  const current = await fs.readFile(target, "utf8");
  const next = patcher(current);

  if (next === current) {
    log(`bez zmian: ${relativePath}`);
    return;
  }

  await backup(relativePath);
  log(`patch: ${relativePath}`);

  if (!DRY_RUN) {
    await fs.writeFile(target, next, "utf8");
  }
}

function replaceOnce(source, needle, replacement, label) {
  const first = source.indexOf(needle);

  if (first < 0) {
    throw new Error(`Nie znaleziono kotwicy "${label}". Repo mogło się zmienić.`);
  }

  if (source.indexOf(needle, first + needle.length) >= 0) {
    throw new Error(`Kotwica "${label}" nie jest jednoznaczna.`);
  }

  return source.slice(0, first) + replacement + source.slice(first + needle.length);
}

function insertAfterOnce(source, needle, addition, label) {
  return replaceOnce(source, needle, `${needle}${addition}`, label);
}

function transformSection(source, startNeedle, endNeedle, transformer, label) {
  const start = source.indexOf(startNeedle);

  if (start < 0) {
    throw new Error(`Nie znaleziono początku sekcji "${label}".`);
  }

  const end = source.indexOf(endNeedle, start + startNeedle.length);

  if (end < 0) {
    throw new Error(`Nie znaleziono końca sekcji "${label}".`);
  }

  const before = source.slice(0, start);
  const section = source.slice(start, end);
  const after = source.slice(end);
  const transformed = transformer(section);

  return before + transformed + after;
}

function removeRegex(source, regex, label) {
  const matches = source.match(regex);

  if (!matches) {
    if (source.includes("@humanet-marketing-patched")) return source;
    throw new Error(`Nie znaleziono fragmentu do usunięcia: ${label}`);
  }

  return source.replace(regex, "");
}

async function computeLegalHashes() {
  const termsPath = path.join(ROOT, "content/legal/regulamin.md");
  const privacyPath = path.join(ROOT, "content/legal/polityka-prywatnosci.md");

  const [terms, privacy] = await Promise.all([
    fs.readFile(termsPath, "utf8"),
    fs.readFile(privacyPath, "utf8"),
  ]);

  return {
    terms: crypto.createHash("sha256").update(terms).digest("hex"),
    privacy: crypto.createHash("sha256").update(privacy).digest("hex"),
  };
}

async function verifyRepository() {
  const packagePath = path.join(ROOT, "package.json");

  if (!(await exists(packagePath))) {
    throw new Error("Uruchom instalator w katalogu głównym repozytorium.");
  }

  const packageJson = JSON.parse(await fs.readFile(packagePath, "utf8"));

  if (packageJson.name !== "humanet-values") {
    throw new Error(
      `Oczekiwano repozytorium humanet-values, wykryto: ${
        packageJson.name ?? "brak"
      }`,
    );
  }
}

async function patchSchemaExports() {
  await patchFile("drizzle/schema/control/index.ts", (source) => {
    const exports = [
      'export * from "./purchase-intents";',
      'export * from "./legal-documents";',
      'export * from "./legal-acceptances";',
      'export * from "./consent-records";',
      'export * from "./consultation-entitlements";',
    ];

    let next = source.trimEnd();

    for (const line of exports) {
      if (!next.includes(line)) next += `\n${line}`;
    }

    return `${next}\n`;
  });
}

