async function patchPurchaseActionV4() {
  await patchFile(
    "features/report-access/api/report-access-purchase.actions.ts",
    (source) => {
      if (source.includes("@humanet-marketing-patched:purchase-action-v4")) {
        return source;
      }

      let next = transformSection(
        source,
        "export async function unlockReportAccessPlaceholderAction(",
        "export type ReportAccessPurchaseState",
        (section) => {
          const b2cBlockRegex =
            /\n[ \t]*const b2cOffer = readReportAccessB2cOffer\(offer\.product\.config\);[\s\S]*?"Konfiguracja pakietu produktu zmieniła się\. Wróć do \/start i wybierz ofertę ponownie\.",[ \t\r\n]*\);[ \t\r\n]*\}/g;

          let cleaned = section.replace(b2cBlockRegex, "\n");

          const productGuardRegex =
            /  if \(!offer\.product\) \{[\s\S]*?return fail\("Dla tego raportu nie ma aktywnego produktu sprzedażowego\."\);\s*\}/;

          const guard = cleaned.match(productGuardRegex)?.[0];

          if (!guard) {
            throw new Error(
              "Nie znaleziono walidacji aktywnego produktu w checkoutcie.",
            );
          }

          const block = `

  const b2cOffer = readReportAccessB2cOffer(offer.product.config);

  if (
    purchaseIntent &&
    (!b2cOffer || b2cOffer.offerCode !== purchaseIntent.offerCode)
  ) {
    return fail(
      "Konfiguracja pakietu produktu zmieniła się. Wróć do /start i wybierz ofertę ponownie.",
    );
  }`;

          cleaned = cleaned.replace(guard, `${guard}${block}`);
          return cleaned;
        },
        "cleanup b2cOffer w unlockReportAccessPlaceholderAction",
      );

      const importLine =
        'import { readReportAccessB2cOffer } from "@/features/report-access/lib/report-access-product-offer";';

      const firstImport = next.indexOf(importLine);
      if (firstImport >= 0) {
        let duplicate = next.indexOf(
          importLine,
          firstImport + importLine.length,
        );

        while (duplicate >= 0) {
          next =
            next.slice(0, duplicate) +
            next.slice(duplicate + importLine.length);
          duplicate = next.indexOf(
            importLine,
            firstImport + importLine.length,
          );
        }
      }

      const marker = next.includes(
        "@humanet-marketing-patched:purchase-action-v3",
      )
        ? "// @humanet-marketing-patched:purchase-action-v3"
        : "// @humanet-marketing-patched:purchase-action";

      if (!next.includes(marker)) {
        throw new Error(
          "Nie znaleziono markera integracji purchase action.",
        );
      }

      return next.replace(
        marker,
        `${marker}\n// @humanet-marketing-patched:purchase-action-v4`,
      );
    },
  );
}

