async function patchPackageLint() {
  const relativePath = "package.json";
  const target = path.join(ROOT, relativePath);
  const current = await fs.readFile(target, "utf8");
  const packageJson = JSON.parse(current);

  if (packageJson.scripts?.lint !== "next lint") {
    return;
  }

  packageJson.scripts.lint = "eslint .";
  const next = `${JSON.stringify(packageJson, null, 2)}\n`;

  await backup(relativePath);
  log("patch: package.json (Next 16 lint)");

  if (!DRY_RUN) {
    await fs.writeFile(target, next, "utf8");
  }
}

async function patchEnvExample() {
  const candidates = [".env.example", ".env.local.example"];
  let relativePath = ".env.marketing.example";

  for (const candidate of candidates) {
    if (await exists(path.join(ROOT, candidate))) {
      relativePath = candidate;
      break;
    }
  }

  const target = path.join(ROOT, relativePath);
  let current = (await exists(target))
    ? await fs.readFile(target, "utf8")
    : "";

  current = current
    .replace(/^HUMANET_OFFER_REPORT_PRODUCT_CODE=.*\n?/gm, "")
    .replace(/^HUMANET_OFFER_REPORT_PLUS_CONSULTATION_PRODUCT_CODE=.*\n?/gm, "")
    .replace(/^HUMANET_OFFER_DECISION_SUPPORT_PRODUCT_CODE=.*\n?/gm, "");

  const marker = "# HUMANET marketing purchase + consent";
  const requiredLines = [
    "NEXT_PUBLIC_CONSENT_VERSION=2026-08-01",
    "NEXT_PUBLIC_GTM_ID=",
    "NEXT_PUBLIC_GA_MEASUREMENT_ID=",
    "NEXT_PUBLIC_CLARITY_PROJECT_ID=",
    "HUMANET_REPORT_TYPE_RELATIONS_QUESTIONNAIRE_CODE=HUMANET_VALUES_IND",
    "HUMANET_REPORT_TYPE_WORK_QUESTIONNAIRE_CODE=HUMANET_VALUES_COOP",
    "HUMANET_REPORT_TYPE_CHANGE_QUESTIONNAIRE_CODE=HUMANET_CHANGE",
    "LEGAL_TERMS_VERSION=2026-08-01",
    "LEGAL_PRIVACY_VERSION=2026-08-01",
    "MARKETING_EMAIL_CONSENT_VERSION=2026-08-01",
    "NEXT_PUBLIC_CALCOM_REPORT_60_URL=",
    "NEXT_PUBLIC_CALCOM_DECISION_90_URL=",
    "NEXT_PUBLIC_CALCOM_GENERAL_CONSULTATION_URL=",
    "CALCOM_WEBHOOK_SECRET=",
  ];

  let next = current.trimEnd();
  if (!next.includes(marker)) {
    next += `${next ? "\n\n" : ""}${marker}`;
  }

  for (const line of requiredLines) {
    const key = line.split("=")[0];
    const regex = new RegExp(`^${key.replace(/[.*+?^${}()|[\\]\\]/g, "\\$&")}=.*$`, "m");
    if (regex.test(next)) {
      // Preserve explicit user/example value if already present.
      continue;
    }
    next += `\n${line}`;
  }

  next += "\n";

  if (next === `${current.trimEnd()}\n`) return;

  await backup(relativePath);
  log(`uzupełnienie zmiennych: ${relativePath}`);

  if (!DRY_RUN) {
    await fs.writeFile(target, next, "utf8");
  }
}

function run(command, commandArgs) {
  return new Promise((resolve, reject) => {
    const child = spawn(command, commandArgs, {
      cwd: ROOT,
      stdio: "inherit",
      shell: process.platform === "win32",
    });

    child.on("error", reject);
    child.on("exit", (code) => {
      if (code === 0) resolve();
      else reject(new Error(`${command} zakończył się kodem ${code}`));
    });
  });
}

async function generateMigrationIfPossible() {
  if (DRY_RUN || SKIP_GENERATE) {
    log("pominięto generowanie migracji");
    return;
  }

  if (!(await exists(path.join(ROOT, "node_modules")))) {
    log(
      "node_modules nie istnieje — nie wygenerowano migracji. Uruchom po instalacji: npm run db:generate -- --name humanet_marketing_purchase_consent",
    );
    return;
  }

  log("generowanie migracji Drizzle");
  await run("npm", [
    "run",
    "db:generate",
    "--",
    "--name",
    "humanet_marketing_purchase_consultations",
  ]);
}

async function main() {
  await verifyRepository();
  const legalHashes = await computeLegalHashes();

  log(DRY_RUN ? "tryb dry-run" : "rozpoczęcie instalacji");

  for (const [relativePath, rawContent] of Object.entries(FILES)) {
    const content = rawContent
      .replaceAll("__TERMS_HASH__", legalHashes.terms)
      .replaceAll("__PRIVACY_HASH__", legalHashes.privacy);

    await writeFile(relativePath, content);
  }

  await patchSchemaExports();
  await patchReportAccessQuery();
  await patchPurchaseAction();
  await patchPurchaseActionV4();
  await patchReportAccessAdminQueries();
  await patchReportAccessAdminActions();
  await patchReportAccessAdminPage();
  await patchReportAccessAdminPageV2();
  await patchUnlockForm();
  await patchUnlockFormV2();
  await patchWebhook();
  await patchCompletedReportLink();
  await patchLoginForm();
  await patchLoginPage();
  await patchPaymentReturnPage();
  await patchNavigation();
  await patchConsultationNavigationV2();
  await patchPackageLint();
  await patchEnvExample();
  await generateMigrationIfPossible();

  const manifest = {
    installer: "install-humanet-values-marketing.mjs",
    installedAt: new Date().toISOString(),
    dryRun: DRY_RUN,
    files: Object.keys(FILES),
    patches: [
      "schema exports",
      "report productCode resolution",
      "B2C product matrix: reportTemplateId + offerCode",
      "report access admin B2C package/price configuration + conditional consultation field + live refresh",
      "existing checkout purchase intent integration v2",
      "unlock form",
      "P24 webhook",
      "completed report purchase link",
      "login privacy checkbox removal",
      "terms acceptance moved from global gate to B2C checkout",
      "login callback preservation",
      "payment return success redirect",
      "privacy and consultation navigation",
      "persistent /my/consultations + Cal.com webhook sync",
      "admin consultation schedule/meeting/report shortcuts",
      "Next 16 lint script",
    ],
    digest: crypto
      .createHash("sha256")
      .update(JSON.stringify(FILES))
      .digest("hex"),
  };

  if (!DRY_RUN) {
    await fs.writeFile(
      path.join(ROOT, ".humanet-values-marketing-install.json"),
      `${JSON.stringify(manifest, null, 2)}\n`,
      "utf8",
    );
  }

  log("gotowe");
  log("uruchom: npm test && npm run lint && npm run build");
  log("przejrzyj migrację przed uruchomieniem na bazie");
  log("skonfiguruj pakiety, ceny i webhook Cal.com zgodnie z docs/marketing-purchase-consent-install.md");
}

main().catch((error) => {
  console.error("[humanet-values] błąd:", error);
  process.exitCode = 1;
});
